// Cook-Torrance 镜面 BRDF（教学近似，逐像素在 CPU 上算）
float D_GGX(float NoH, float rough) {
  float a = rough * rough;
  float a2 = a * a;
  float d = NoH * NoH * (a2 - 1.0) + 1.0;
  return a2 / (PI * d * d);
}
float F_Schlick(float VoH, vec3 F0) {
  return F0 + (1.0 - F0) * pow(1.0 - VoH, 5.0);
}
float G_Smith(float NoL, float NoV, float rough) {
  float k = pow(rough + 1.0, 2.0) / 8.0;
  float gl = NoL / (NoL * (1.0 - k) + k);
  float gv = NoV / (NoV * (1.0 - k) + k);
  return gl * gv;
}
vec3 spec = D * G * F / (4.0 * NoL * NoV);
vec3 kd = (1.0 - metallic);
vec3 diffuse = kd * albedo / PI;
