// GLSL ES 3.x：OES 纹理采样后做 YUV → RGB（BT.601 limited range 近似）
uniform sampler2D uTexture;      // GL_TEXTURE_EXTERNAL_OES
in vec2 vTexCoord;
out vec4 fragColor;

void main() {
  vec3 yuv = texture(uTexture, vTexCoord).rgb;
  float y  = yuv.r;
  float u  = yuv.g - 0.5;
  float v  = yuv.b - 0.5;
  vec3 rgb;
  rgb.r = y + 1.402 * v;
  rgb.g = y - 0.344 * u - 0.714 * v;
  rgb.b = y + 1.772 * u;
  fragColor = vec4(clamp(rgb, 0.0, 1.0), 1.0);
}

// 播放器主循环的音视频同步（简化伪代码）
while (!stopped) {
  Packet pkt = demuxer.read();          // 按 DTS 顺序送入解码器
  Frame frame = decoder.decode(pkt);    // 解码输出已按 DTS 排好
  reorderBuffer.push(frame);            // 按 PTS 重新排序

  double audioClock = audioPlayer.pts();
  Frame next = reorderBuffer.peek();
  if (next.pts <= audioClock) {
    render(next);                        // 视频 PTS 追上主时钟才上屏
    reorderBuffer.pop();
  } else {
    sleepFor(next.pts - audioClock);     // 提前了就等待
  }
}

